    m=e['manifest']
    c.o.require(m['operation']=='replace-gas-city-control-plane.v1' and m['sequence']==14
                and m['bead']=='ga-ecwh','unreviewed broker request')
    c.o.require(m['artifact']==dict(sha256=c.NEW,size=c.NEW_SIZE),'artifact binding')
    c.o.require(m['schema']=='gc.privileged-provision-manifest.v1' and m['source']==SOURCE,'source binding')
    c.o.require(m['expected']==dict(sha256=c.OLD,uid=1000,gid=1000,mode='0755'),'predecessor binding')
    # Remaining source/expected/signature checks are the unchanged broker's
    # responsibility plus the required independent full-envelope review.
    return timestamp(m['issued_at']),timestamp(m['expires_at'])

