def verified_receipt(binding,host,before_host):
    request=binding['envelope_sha256']
    c.o.require(len(request)==64 and all(x in '0123456789abcdef' for x in request),'request identity')
    path=Path('/var/lib/gas-city-provisioning/receipts')/(request+'.json')
    pin=c.s.pin(path,{})
    c.o.require(pin['uid']==0 and pin['gid']==986 and pin['mode']==0o640 and pin['size']<=65536,'receipt custody')
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
    try:
        before=os.fstat(fd);data=os.read(fd,65537)
        c.o.require(before==os.fstat(fd) and len(data)==before.st_size==pin['size'],'receipt read race')
    finally:os.close(fd)
    c.o.require(hashlib.sha256(data).hexdigest()==pin['sha256'],'receipt digest race')
    receipt=json.loads(data)
    manifest=c.s.read(ROOT/'envelope.json',request)['manifest']
    validate_receipt(receipt,manifest,request,host,before_host)
    return dict(path=str(path),pin=pin,receipt=receipt)

def validate_receipt(receipt,manifest,request,host,before_host):
    c.o.require(receipt['schema']=='gc.privileged-provision-receipt.v1'
                and receipt['request_id']==request and receipt['sequence']==14
                and receipt['bead']=='ga-ecwh' and receipt['operation']=='replace-gas-city-control-plane.v1'
                and receipt['result']=='pass' and receipt['rollback']=='not-needed','receipt result binding')
    c.o.require(receipt['source']==manifest['source'],'receipt source binding')
    c.o.require(receipt['before']==dict(sha256=c.OLD,size=134048098,uid=1000,gid=1000,mode='0755')
                and receipt['after']==dict(sha256=c.NEW,size=c.NEW_SIZE,uid=1000,gid=1000,mode='0755'),'receipt artifact binding')
    unit='gascity-supervisor-home-42adab5d.service'
    for key,actual in (('service_before',before_host['core']),('service_after',host['core'])):
        c.o.require(set(receipt[key])=={unit},'receipt service scope')
        expected={k:actual[k] for k in ('ActiveState','ExecMainStartTimestampMonotonic','MainPID','NRestarts','Result','SubState')}
        c.o.require(receipt[key][unit]==expected,'receipt service epoch binding')

def submit(args):
    b=baseline(args.baseline_sha256);binding=load_binding(args,b)
    c.o.require(c.s.pin(BROKER,{})==dict(sha256=BROKER_SHA,uid=0,gid=0,mode=0o755,size=60424),
                'installed broker ordinary pin drift')
    fd=sealed_envelope(binding['envelope_sha256'])
    try:
        c.timer_inactive();checked_capture(b,binding,False)
        outputs_absent('submit')
        budget=fence(b,binding)
        c.o.require(budget>31*d.SECOND,'insufficient one-shot submission budget')
        result=subprocess.run([str(BROKER),'apply','--envelope','/proc/self/fd/'+str(fd)],
                              pass_fds=(fd,),capture_output=True,text=True,timeout=30,check=False)
        record('broker-result.json',dict(returncode=result.returncode,stdout=result.stdout,stderr=result.stderr))
        c.o.require(result.returncode==0 and c.o.decode(result.stdout.encode()).get('ok') is True,
                    'broker did not return exact success; inspect receipt, no retry')
        fence(b,binding)
    finally:os.close(fd)
    return dict(result_sha256=c.s.digest(ROOT/'broker-result.json'))

def sealed_envelope(digest):
    pin,data=c.o.read_file(ROOT/'envelope.json',collect=True)
    c.o.require(pin['sha256']==digest,'submission envelope drift')
    value=c.o.decode(data)
    canonical=(json.dumps(value,ensure_ascii=True,sort_keys=True,separators=(',',':'))+'\n').encode()
    c.o.require(canonical==data,'envelope must be broker-canonical bytes')
    fd=os.memfd_create('ga-e0t1.15-reviewed-envelope',os.MFD_CLOEXEC|os.MFD_ALLOW_SEALING)
    try:
        view=memoryview(data)
        while view:
            count=os.write(fd,view);c.o.require(count>0,'sealed envelope short write');view=view[count:]
        seals=fcntl.F_SEAL_WRITE|fcntl.F_SEAL_GROW|fcntl.F_SEAL_SHRINK|fcntl.F_SEAL_SEAL
        fcntl.fcntl(fd,fcntl.F_ADD_SEALS,seals)
        c.o.require(fcntl.fcntl(fd,fcntl.F_GET_SEALS)==seals,'envelope seal proof')
        os.lseek(fd,0,os.SEEK_SET);actual=hashlib.sha256()
        while True:
            block=os.read(fd,1048576)
            if not block:break
            actual.update(block)
        c.o.require(actual.hexdigest()==digest,'sealed bytes differ')
        os.lseek(fd,0,os.SEEK_SET)
        return fd
    except BaseException:
        os.close(fd);raise

def main():
    c.o.require(sys.flags.isolated and sys.flags.dont_write_bytecode and sys.flags.optimize==0,
                'use python3 -I -B')
    parser=argparse.ArgumentParser();parser.add_argument('phase',choices=PHASES)
    for name in ('baseline','binding','envelope','first'):parser.add_argument('--'+name+'-sha256')
    args=parser.parse_args()
    fd=os.open(ROOT/'execution.lock',os.O_CREAT|os.O_RDWR|os.O_NOFOLLOW|os.O_CLOEXEC,0o600)
    try:
        fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
        action=prepare if args.phase=='prepare' else lambda:(bind(args) if args.phase=='bind-envelope'
                    else submit(args) if args.phase=='submit' else observe(args))
        result=run_phase(args.phase,action)
        print(json.dumps(dict(ok=True,phase=args.phase,result=result),sort_keys=True))
    finally:os.close(fd)


